def frozen(d):
  f=read(d/'freeze.json')['files'];items=f.items() if isinstance(f,dict) else [(r['path'],r) for r in f];expected={}
  for n,r in items:
   p=Path(n);n=str(p.relative_to(d)) if p.is_absolute() else n
   assert not Path(n).is_absolute() and '..' not in Path(n).parts and n not in expected
   expected[n]=r
  assert set(expected)=={str(p.relative_to(d)) for p in d.rglob('*') if p.is_file() and p!=d/'freeze.json'}
  for n,r in expected.items():check(d/n,r)
  return dict(path=str(d),freeze=pin(d/'freeze.json'),files=len(expected))

def frozen(row):
  d=Path(row['directory']);manifest=Path(row['freeze']['path'])
  if 'angle' in row:f=original_freeze(row)
  else:
   assert manifest==d/'freeze.json'
   f=json.loads(pinned(row['freeze']))['files'];assert isinstance(f,dict)
  items=f.items();expected={}
  for n,r in items:
   p=Path(n);n=str(p.relative_to(d)) if p.is_absolute() else n
   assert not Path(n).is_absolute() and '..' not in Path(n).parts and n not in expected
   expected[n]=r
  assert set(expected)=={str(p.relative_to(d)) for p in d.rglob('*') if p.is_file() and p!=manifest}
  for n,r in expected.items():check(d/n,r)
  return dict(path=str(d),freeze=pin(manifest),files=len(expected))
